```bash
cd /home/vscode/nullness-benchmarks/litiengine && cat <<'EOF' > src/de/gurkenlabs/litiengine/environment/tilemap/IMapObject.java
package de.gurkenlabs.litiengine.environment.tilemap;

import de.gurkenlabs.litiengine.resources.Resource;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Point2D;
import java.awt.geom.Rectangle2D;
import javax.annotation.Nullable;

/**
 * This interface represents an instance on a map that can define various things for an engine. e.g.
 * it can be used to define static collision boxes or other special regions on the map.
 */
public interface IMapObject extends ICustomPropertyProvider, Resource {

  /**
   * Gets the grid id.
   *
   * @return the grid id
   */
  public int getGridId();

  @Nullable
  public ITilesetEntry getTile();

  /**
   * Gets the hit box.
   *
   * @return the hit box
   */
  public Rectangle2D getBoundingBox();

  /**
   * Gets the id.
   *
   * @return the id
   */
  public int getId();

  /**
   * Gets the location.
   *
   * @return the location
   */
  public Point2D getLocation();

  @Nullable
  public String getType();

  @Nullable
  public IPolyShape getPolyline();

  @Nullable
  public IPolyShape getPolygon();

  @Nullable
  public Ellipse2D getEllipse();

  @Nullable
  public IMapObjectText getText();

  public IMapObjectLayer getLayer();

  public void setGridId(int gid);

  public void setId(int id);

  public void setType(String type);

  public void setX(float x);

  public void setY(float y);

  public void setLocation(Point2D location);

  public void setLocation(float x, float y);

  public void setWidth(float width);

  public void setHeight(float height);

  public float getX();

  public float getY();

  public float getWidth();

  public float getHeight();

  public boolean isPolyline();

  public boolean isPolygon();

  public boolean isPoint();

  public boolean isEllipse();

  public void setPolyline(IPolyShape polyline);

  public void setPolygon(IPolyShape polygon);
}
EOF
```

